import json
import os
import re
import sys
from pathlib import Path

PROJECT = Path(__file__).resolve().parents[1]
ROOT = PROJECT.parents[1]
sys.path.insert(0, str(ROOT))
os.environ.setdefault("QA_HEAL_LOG", str(PROJECT / "outputs" / "heals.jsonl"))

from core.lib.smart_locator import resolve  # noqa: E402

CFG = json.loads((PROJECT / "config.json").read_text(encoding="utf-8"))
SHOTS = PROJECT / "screenshots" / "run"
SHOTS.mkdir(parents=True, exist_ok=True)


def val(text):
    """Fill {credentials.username}-style placeholders from config.json."""
    def sub(m):
        cur = CFG
        for part in m.group(1).split("."):
            cur = cur.get(part, "") if isinstance(cur, dict) else ""
        return str(cur)
    return re.sub(r"\{\{\s*([\w.]+)\s*\}\}", sub, text)


def test_log_in_add_the_first_item(page):
    page.set_default_timeout(60000)
    page.goto(CFG["base_url"], wait_until="domcontentloaded")

    # step 1: log in
    el = resolve(page, (
        [{'kind': 'role', 'role': 'textbox', 'value': 'Username'}, {'kind': 'label', 'value': 'Username'},
         {'kind': 'placeholder', 'value': 'Username'}, {'kind': 'id', 'value': 'username'},
         {'kind': 'name', 'tag': 'input', 'value': 'username'}, {'kind': 'css', 'value': '#username'}]
    ))
    el.fill(val('{{credentials.username}}'))
    page.wait_for_load_state('domcontentloaded')
    el = resolve(page, (
        [{'kind': 'role', 'role': 'textbox', 'value': 'Password'}, {'kind': 'label', 'value': 'Password'},
         {'kind': 'placeholder', 'value': 'Password'}, {'kind': 'id', 'value': 'password'},
         {'kind': 'name', 'tag': 'input', 'value': 'password'}, {'kind': 'css', 'value': '#password'}]
    ))
    el.fill(val('{{credentials.password}}'))
    page.wait_for_load_state('domcontentloaded')
    el = resolve(page, (
        [{'kind': 'role', 'role': 'button', 'value': 'Log in'}, {'kind': 'id', 'value': 'login-button'},
         {'kind': 'text', 'value': 'Log in'}, {'kind': 'css', 'value': '#login-button'}]
    ))
    el.click()
    page.wait_for_load_state('domcontentloaded')
    page.screenshot(path=str(SHOTS / 'step_01.png'))

    # step 2: add the first item to the cart
    el = resolve(page, (
        [{'attr': 'data-test', 'kind': 'test_id', 'value': 'add-backpack'},
         {'kind': 'role', 'role': 'button', 'value': 'Add to cart'}, {'kind': 'text', 'value': 'Add to cart'},
         {'kind': 'css', 'value': 'body > ul > li:nth-of-type(1) > button'}]
    ))
    el.click()
    page.wait_for_load_state('domcontentloaded')
    page.screenshot(path=str(SHOTS / 'step_02.png'))

    # step 3: open the cart
    el = resolve(page, (
        [{'kind': 'role', 'role': 'link', 'value': 'Cart 1'}, {'kind': 'id', 'value': 'cart-link'},
         {'kind': 'text', 'value': 'Cart 1'}, {'kind': 'css', 'value': '#cart-link'}]
    ))
    el.click()
    page.wait_for_load_state('domcontentloaded')
    page.screenshot(path=str(SHOTS / 'step_03.png'))

    # step 4: verify "Canvas Backpack" is in the cart
    assert 'canvas backpack' in page.inner_text('body').lower(), 'expected text not on page: ' + 'Canvas Backpack'
    page.screenshot(path=str(SHOTS / 'step_04.png'))
